@import '../../../css/colors.css';

.list {
  list-style: none;

  margin: 0;
  padding-left: 0;

  /* ensure list takes up maximum vertical space amount between column header and user list */
  flex-grow: 1;

  overflow-y: hidden;
  &:global(.overflowed) {
    overflow-y: scroll;
